void myproject(
    hls::stream<input_t> &input_layer,
    hls::stream<result_t> &layer11_out
) {


#pragma HLS INTERFACE axis port=input_layer,layer11_out
#pragma HLS DATAFLOW
# 34 "/home/ncgadmin/Bachelor/HLS4ML_testbench_KV260/development/hgq2/3/hls4ml_prj_VitisUnified_2025/firmware/myproject.cpp"
    hls::stream<conv2d_result_t> layer2_out("layer2_out");
#pragma HLS STREAM variable=layer2_out depth=676

    hls::stream<layer3_t> layer3_out("layer3_out");
#pragma HLS STREAM variable=layer3_out depth=676

    hls::stream<layer4_t> layer4_out("layer4_out");
#pragma HLS STREAM variable=layer4_out depth=169

    hls::stream<conv2d_1_result_t> layer5_out("layer5_out");
#pragma HLS STREAM variable=layer5_out depth=121

    hls::stream<layer6_t> layer6_out("layer6_out");
#pragma HLS STREAM variable=layer6_out depth=121

    hls::stream<layer7_t> layer7_out("layer7_out");
#pragma HLS STREAM variable=layer7_out depth=25

    auto& layer8_out = layer7_out;
    hls::stream<dense_result_t> layer10_out("layer10_out");
#pragma HLS STREAM variable=layer10_out depth=1

    nnet::conv_2d_cl<input_t, conv2d_result_t, config2>(input_layer, layer2_out, w2, b2);

    nnet::relu<conv2d_result_t, layer3_t, relu_config3>(layer2_out, layer3_out);

    nnet::pooling2d_cl<layer3_t, layer4_t, config4>(layer3_out, layer4_out);

    nnet::conv_2d_cl<layer4_t, conv2d_1_result_t, config5>(layer4_out, layer5_out, w5, b5);

    nnet::relu<conv2d_1_result_t, layer6_t, relu_config6>(layer5_out, layer6_out);

    nnet::pooling2d_cl<layer6_t, layer7_t, config7>(layer6_out, layer7_out);

    nnet::dense<layer7_t, dense_result_t, config10>(layer8_out, layer10_out, w10, b10);

    nnet::softmax<dense_result_t, result_t, softmax_config11>(layer10_out, layer11_out);

}
